import numpy as np

def get_dist(r, c, r0, r1, c0, c1):
    return max(abs(r - r0), abs(r - r1), abs(c - c0), abs(c - c1))

def get_layers_at_dist(r0, r1, c0, c1, grid_np):
    """Get unique non-zero values at each distance"""
    center_r = r0 + (r1-r0)//2
    center_c = c0 + (c1-c0)//2
    max_d = get_dist(center_r, center_c, r0, r1, c0, c1)

    layers = {}
    for d in range(max_d + 1):
        vals = set()
        # Check border cells (d=0)
        if d == 0:
            for c in range(c0, c1 + 1):
                vals.add(grid_np[center_r, c])
            for r in range(r0, r1 + 1):
                vals.add(grid_np[r, center_c])
        else:
            # Check all cells in box at distance d
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    dcell = get_dist(r, c, r0, r1, c0, c1)
                    if dcell == d:
                        vals.add(grid_np[r, c])
        layers[d] = vals

    return layers

